R=Path(__file__).resolve().parents[3];K=Path(__file__).resolve().parent;B=K/'batches/edition-24';S=R/'projects/site';now=datetime.now(timezone.utc).isoformat()
q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(471, 'the-dark-pan-remembers', 'The dark pan remembers', 'The black iron tawa carries the labour of feeding a family and a childhood memory of chakuli. A close working surface honours its use and heat without staging the mother or five children.', 'Original horizontal 3:2 close matte gouache and charcoal kitchen study. A plain round seasoned black iron tawa, shallow and unadorned, rests securely across the top of a simple earthen cooking stove; only part of the stove and its dark mouth are visible. On the pan one thin small pale chakuli pitha, a soft rice-and-lentil pancake with small irregular pores and lightly cooked edge, sits slightly off-centre. No thick fluffy American pancake, syrup, toppings or food styling. The pan’s dark surface is softly uneven with a modest heat sheen, not mirror-polished. A low ordinary glow inside the stove, no flames licking unrealistically around the food. Tight crop, near-level oblique view, much of surrounding kitchen fades into quiet earth-grey paint. No hands, faces, utensils, plated feast, smoke ribbons, text, ornament or decorative dirt. Warmth and the dignity of ordinary sustained work.'), (474, 'tea-under-the-shade', 'Tea under the shade', 'The invitation is to meet simply, sip tea and recover childhood friendship beyond complaints or status. Two cups at an ordinary shaded outdoor seat suggest the conversation without inventing the friends.', 'Original horizontal 3:2 loose warm pastel and watercolor, slightly elevated view of one end of an ordinary rough wooden outdoor bench beneath a leafy tree. Two small plain earthen tea cups stand on the broad seat with unequal spacing, one nearer the lower edge and one farther back, both steady and upright; a little milky tea visible in each at different levels. Tree shade falls in a few soft overlapping patches over the bench, not evenly dotted. A blurred ordinary earth yard beyond, no lush garden design, no ornate café, no table setting, no saucers, no flowers, no staged book, no perfect steam curls. Crop the rest of the bench at left; right half mostly quiet muted yard and shade. Soft available daylight, unpolished clay rims and believable cup bases. Intimacy of an unhurried meeting, not rustic lifestyle advertising. No people, faces, text or logos.'), (478, 'the-line-between', 'The line between', 'A hairline crack becomes the fault line of a relationship. The poem is small and direct, so one restrained imperfect line across painted plaster is enough; no literal wounds or dramatic ruined wall.', 'Original horizontal 3:2 minimal graphite and thin chalky gouache study of an ordinary pale blue-grey painted plaster wall, seen nearly front-on. A single thin irregular hairline crack begins near top left of centre and travels diagonally downward a short distance, branches once very subtly, then becomes faint before reaching bottom. Tiny paint-edge lifting only immediately along one short section, not widespread peeling or decay. Most of the wall is empty low-detail matte colour, gently warmer at one edge from indirect daylight. No door, window, furniture, framed photograph, gold repair, human silhouette, body wound or text. Close quiet observational drawing, slight paper tooth rather than decorative texture. The crack should remain a vulnerable fine line, not lightning, a canyon or a graphic logo.')]
items=[]
for pid,ident,title,reason,scene in rows:
 p=S/f'content/editions/issue-24/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/f'poem-{pid}.json';snapshot.write_bytes(p.read_bytes())
 prompt=f'Use case: illustration-story. Original horizontal 3:2 literary artwork for Kabita Live Issue24. Human Natural in Poetic Natural mode. Preserve the selected expressive medium; a painted interpretation, never documentary evidence.\nEmotional anchor: {reason}\nScene and medium: {scene}\nAnti-optimization checks: avoid staged object display, equal detail everywhere, mechanically repeated shapes, theatrical lighting and cosmetic distress. Material contact, geometry and illumination must make sense. Preserve quiet negative space and emotional ambiguity. No identifiable real people, portraits, readable text, signature, logos or watermark. No people, portraits or documentary location claims. Opaque ivory-paper background.\nPoem {d["title"]} by {d["author"]}; source read fully, use as context only, never render the words:\n{d["text"]}\n'
 pp=B/f'{ident}-prompt.txt';pp.write_text(prompt)
 items.append(dict(id=ident,edition=24,poem_id=pid,title=title,rationale=reason,status='pending',prompt=str(pp.relative_to(R)),poem_source=str(p.relative_to(R)),poem_evidence=str(snapshot.relative_to(R)),poem_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),output=f'kb/artifacts/artwork/edition-art-rollout-2026-10-04/edition-24/{ident}/v1.png',attempts=[],independent=False))
plain=[{'poem_id': 470, 'rationale': 'Fear, desire and the speaker’s final self-questioning shift across a long intimate monologue. Preserve that complexity without an invented woman, ritual costume or literal body metaphor.', 'status': 'pending'}, {'poem_id': 472, 'rationale': 'The interfaith allegory brings Allah and Bhagwan together through ordinary generosity. Keep its reveal in words and avoid invented depictions of divine figures or a literal temple inside a person.', 'status': 'pending'}, {'poem_id': 477, 'rationale': 'Words become many living and ritual forms across the poem; a text-led opening preserves movement without a crowded collage or illustrated author identity.', 'status': 'pending'}]
for p in (S/'content/editions/issue-24').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
b=dict(edition=24,status='planned',created_at=now,poems_read=sorted(json.loads(p.read_text())['id'] for p in (S/'content/editions/issue-24').glob('poem-*.json')),direction='October finds relationship in ordinary surfaces: an iron pan carrying family memory, two cups under tree shade, and a hairline crack. Dense charcoal-gouache warmth, loose pastel companionship and a near-empty graphite wall vary visual weight. Intimate monologue, interfaith allegory and transforming language remain text-led.',items=items,text_led=plain,independent=False)
(B/'batch.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n');ed=next(x for x in q['editions'] if x['edition']==24);ed.update(status='planned',artworks=[i['id'] for i in items],text_led=[i['poem_id'] for i in plain],batch=str((B/'batch.json').relative_to(R)),direction=b['direction']);q['active_batch']=dict(id='edition-24',owner='current-chat-assistant',started_at=now,status='running');q['updated_at']=now;(K/'queue.json').write_text(json.dumps(q,ensure_ascii=False,indent=2)+'\n')
print('Edition24 planned; all18 source snapshots retained.')
